(function(){'use strict';const definitions={'first-download':['First download','Your file is ready.'],'controller-paired':['Controller paired','Ready for your next move.'],'universe-changed':['Universe changed','Make this space yours.']};let enabled=false,timer=null,queue=[],seen=new Set();try{enabled=localStorage.getItem('ob.milestones')==='true'}catch(e){}const box=document.querySelector('#milestone'),toggle=document.querySelector('#enabled');toggle.checked=enabled;function clear(){clearTimeout(timer);timer=null;queue=[];box.hidden=true;box.classList.remove('reveal')}function next(){if(!enabled||timer||!queue.length)return;const event=queue.shift(),copy=definitions[event.type];document.querySelector('#milestone-title').textContent=copy[0];document.querySelector('#milestone-detail').textContent=copy[1];box.hidden=false;box.classList.add('reveal');timer=setTimeout(()=>{box.hidden=true;timer=null;box.classList.remove('reveal');next()},3500)}function notify(event){if(!enabled||!event||event.schema!==1||!definitions[event.type]||typeof event.id!=='string'||event.id.length>128||seen.has(event.id))return false;seen.add(event.id);if(seen.size>128)seen.delete(seen.values().next().value);if(queue.length>=3)return false;queue.push(event);next();return true}toggle.onchange=()=>{enabled=toggle.checked;try{localStorage.setItem('ob.milestones',String(enabled))}catch(e){}if(!enabled)clear();document.querySelector('#feedback').textContent=enabled?'Milestones enabled.':'Milestones off.';window.dispatchEvent(new CustomEvent('omnibloom:milestone-setting',{detail:{schema:1,enabled}}))};document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{if(!notify({schema:1,type:b.dataset.event,id:'demo-'+Date.now()}))document.querySelector('#feedback').textContent=enabled?'Already shown or queue full.':'Turn on milestone toasts to preview.';});window.OmniMilestones={notify,setEnabled(value){toggle.checked=Boolean(value);toggle.onchange()},clear};window.addEventListener('pagehide',clear);})();